window.AUTH=window.AUTH||{};window.AUTH["22-10"]={"d":"22-10","id":"2022/22-10","n":"Dubin v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner David Dubin","date":"2022-12-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-10/250824/20221223152000629_22-10%20ts.pdf","side":"pet","n":54},{"k":"respondent","label":"Brief of respondent United States","date":"2023-01-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-10/253000/20230123185001242_Dubin%2022-10.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioner David Dubin","date":"2023-02-16","url":"https://www.supremecourt.gov/DocketPDF/22/22-10/254992/20230216154033125_22-10rb_pdfa.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r34_p86b.pdf","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"a court should not interpret each word in a statute with blinders on, refusing to look at the word’s function within the broader statutory context.","cite":"573 U.S. 169, 179 n.6"}]},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"by":{"0":"2"}},{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"by":{"0":"18, 19, 27","1":"12","2":"15"},"q":[{"src":"brief","b":0,"text":"interpretational difficulties because of the different meanings attributable to it.","cite":"516 U.S. 137, 143"},{"src":"brief","b":0,"text":"the paradoxical statement: ‘I use a gun to protect my house, but I’ve never had to use it.’","cite":"516 U.S. at 143"},{"src":"brief","b":2,"text":"placement and purpose in the statutory scheme.","cite":"516 U.S. 137, 145"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"the word `use' poses some interpretational diffculties because of the different meanings attributable to it.","cite":"516 U. S. 137, 143"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"variously defned as `[t]o convert to one's service,' `to employ,' `to avail oneself of,' and `to carry out a purpose or action by means of.'","cite":"516 U. S., at 145"}]},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"by":{"0":"29"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"0":"passim"},"q":[{"src":"brief","b":0,"text":"there is dissonance between that ordinary meaning and the reach of the definition.","cite":"572 U.S. 844, 861"},{"src":"argument","who":"Justice Gorsuch","text":"In Bond, for example, we -- we made clear that we don't normally interpret federal law to swallow up vast swaths of state law authority as traditionally understood."},{"src":"argument","who":"Justice Sotomayor","text":"In the Bond case, clearly, the woman who poisoned the mistress or the person she suspected of being a mistress wasn't a law-abiding citizen, and we still narrowed that statute, correct?"}]},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"0":"37"}},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"unless Congress conveys its purpose clearly, it will not be deemed to have significantly changed the federal-state balance in the prosecution of crimes.","cite":"531 U.S. 12, 25"}]},{"t":"case","label":"Commonwealth v. Brown","cite":"21 S.E. 357","y":1895,"court":"Va.","url":"https://www.courtlistener.com/c/S.E./21/357/","by":{"0":"41"}},{"t":"case","label":"People ex rel. Failing v. Hwy. Comm’rs of Town of Palatine","cite":"53 Barb. 70","y":1869,"court":"N.Y. Gen. Term.","url":"https://www.courtlistener.com/c/Barb./53/70/","by":{"0":"41"},"q":[{"src":"brief","b":0,"text":"the title of the bill disguises and conceals it.","cite":"53 Barb. 70, 73"},{"src":"brief","b":0,"text":"No person, from reading its title, would ever guess,","cite":"53 Barb. at 73"}]},{"t":"case","label":"Flores-Figueroa v. United States","cite":"556 U.S. 646","y":2009,"id":"2008/08-108","sc":1,"by":{"0":"28","1":"26, 30, 31","2":"14"},"q":[{"src":"brief","b":1,"text":"identity theft (use of an ID belonging to someone else).","cite":"556 U.S. 646, 655"},{"src":"brief","b":2,"text":"in which someone wrongfully obtains and uses another person’s personal data in some way that involves fraud or deception.","cite":"556 U.S. 646"},{"src":"argument","who":"Mr. Fisher","text":"I think that's right, and in Flores-Figueroa, the Court actually, with this particular statute in mind, looked at the title. So there's precedent on the books from this Court as to the usefulness of this title."},{"src":"argument","who":"Justice Sotomayor","text":"But what do we do about the incongruity that under Flores-Figueroa we said fictitious people are not covered by this?"}]},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"by":{"0":"30"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"40"},"q":[{"src":"opinion","who":"Justice Gorsuch, concurring in the judgment","text":"fair notice of the conduct [they] punis[h].","cite":"576 U. S. 591, 595"}]},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"by":{"0":"2"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"by":{"0":"30"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"in light of the terms surrounding [them],","cite":"543 U. S., at 9"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"Congress sought to distinguish for heightened punishment and other crimes.","cite":"543 U. S., at 11"}]},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"by":{"0":"2, 34, 39","2":"3"},"q":[{"src":"argument","who":"Mr. Fisher","text":"And I think what I would direct the Court to are cases like Marinello, cases like Yates, your honest services cases, where over and over the Court has said, when Congress uses broad language, we don't construe those literally in the maximalist way."},{"src":"argument","who":"Mr. Fisher","text":"You know, the Court has had a lot of cases in recent years, I gave Marinello as one example, Van Buren was another recent example that held -- some of the honest services cases are examples where the Court has said not in -- not -- not so much the Rule of Lenity, but they've just said understanding what Congress meant by words, we would not assume Congress would sweep in vast arrays of conduct without doing it clearly."},{"src":"argument","who":"Justice Kavanaugh","text":"In the court of appeals, Judge Costa's opinion said that this Court's precedents had sent an \"unmistakable\" message that \"[c]ourts should not assign federal criminal statutes [of] a 'breath-taking' scope when a narrower reading is reasonable.\" And the Petitioner also cites a long line of cases you're familiar with, Marinello, Van Buren, Kelly, the list goes on, where we have rejected, I would say, the broadest interpretation of criminal statutes, the literal reading as compared to the ordinary reading of criminal statutes, based on fair notice concerns and not trapping the unwary or increasing the sentence on an unwary person."}]},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"by":{"0":"2, 37, 38, 39","2":"21"},"q":[{"src":"brief","b":0,"text":"cannot construe a criminal statute on the assumption that the Government will ‘use it responsibly.’","cite":"579 U.S. at 576"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"Under the familiar interpretive canon noscitur a sociis, `a word is known by the company it keeps.'","cite":"579 U. S. 550, 568–569"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"[T]his canon is often wisely applied where a word is capable of many meanings in order to avoid the giving of unintended breadth to the Acts of Congress.","cite":"579 U. S., at 569"}]},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"by":{"0":"20","1":"11, 12, 14, 30"},"q":[{"src":"brief","b":1,"text":"guns ‘played’ no part in the crime,","cite":"524 U.S. at 137"},{"src":"brief","b":1,"text":"‘played’ no part in the crime,","cite":"524 U.S. at 137"}]},{"t":"case","label":"People v. Carstensen","cite":"420 P.2d 820","y":1966,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/420/820/","by":{"0":"25"}},{"t":"case","label":"People v. Friederich","cite":"185 P. 657","y":1919,"court":"Colo.","url":"https://www.courtlistener.com/c/P./185/657/","by":{"0":"41"}},{"t":"case","label":"Rouleau v. Avrach","cite":"233 So. 2d 1","y":1970,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/233/1/","by":{"0":"41"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"by":{"0":"37, 38","2":"21-22"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"by":{"0":"19, 20, 21, 43","1":"10-14, 30","2":"3, 4"},"q":[{"src":"brief","b":0,"text":"range all the way from ‘to partake of’ (as in ‘he uses tobacco’) to ‘to be wont or accustomed’ (as in ‘he used to smoke tobacco’).","cite":"508 U.S. 223, 241-42"},{"src":"brief","b":0,"text":"is eminently debatable—and that is enough, under the rule of lenity, to require finding for the petitioner here.","cite":"508 U.S. 223, 246"},{"src":"brief","b":1,"text":"some purpose or effect with respect to","cite":"508 U.S. at 238"},{"src":"brief","b":1,"text":"presence or involvement [was] the result of accident or coincidence,","cite":"508 U.S. at 238"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"[a] defendant uses a means of identifcation `in relation to' a predicate offense if the use of that means of identifcation `facilitates or furthers' the predicate offense in some way.","cite":"508 U. S. 223, 232"}]},{"t":"case","label":"State v. Dunn","cite":"267 So. 2d 193","y":1972,"court":"La.","url":"https://www.courtlistener.com/c/So.%202d/267/193/","by":{"0":"25"}},{"t":"case","label":"State v. Harper","cite":"785 P.2d 1341","y":1990,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/785/1341/","by":{"0":"25"}},{"t":"case","label":"State v. Thibeault","cite":"402 A.2d 445","y":1979,"court":"Me.","url":"https://www.courtlistener.com/c/A.2d/402/445/","by":{"0":"25"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"by":{"0":"29"}},{"t":"case","label":"Torres v. Lynch","cite":"578 U.S. 452","y":2016,"id":"2015/14-1096","sc":1,"by":{"0":"18"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"[W]hen [a] choice has to be made between two readings of what conduct Congress has made a crime, it is appropriate, before [choosing] the harsher alternative, to require that Congress should have spoken in language that is clear and definite.","cite":"404 U.S. 336, 347"},{"src":"brief","b":0,"text":"instinctive distaste against men languishing in prison unless the lawmaker has clearly said they should.","cite":"404 U.S. at 348"}]},{"t":"case","label":"United States v. Berroa","cite":"856 F.3d 141","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/856/141/","by":{"0":"38, 43"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"issu[ing] prescriptions that their [actual] patients would then fll at . . . pharmacies.","cite":"856 F. 3d 141, 148, 155–156"}]},{"t":"case","label":"United States v. Croft","cite":"2022 WL 1652742","y":2022,"court":"5th Cir. May 24","by":{"0":"11"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"by":{"0":"36, 42"},"q":[{"src":"brief","b":0,"text":"presume[s] that the same language in related statutes carries a consistent meaning.","cite":"139 S. Ct. 2319, 2329"}]},{"t":"case","label":"United States v. Mahmood","cite":"820 F.3d 177","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/820/177/","by":{"0":"10"}},{"t":"case","label":"United States v. Medlock","cite":"792 F.3d 700","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/700/","by":{"0":"11, 21"}},{"t":"case","label":"United States v. Michael","cite":"882 F.3d 624","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/624/","by":{"0":"21, 22","2":"4, 5"},"q":[{"src":"brief","b":0,"text":"used the means of identification to further or facilitate","cite":"882 F.3d 624, 628"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"mischaracteriz[ing] the nature of the transports, saying that the patients had required stretchers when they had not.","cite":"882 F. 3d 624, 628"},{"src":"opinion","who":"Justice Gorsuch, concurring in the judgment","text":"turns on causation, or at least causation often helps to answer the question.","cite":"882 F. 3d 624, 628"}]},{"t":"case","label":"United States v. Miller","cite":"734 F.3d 530","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/734/530/","by":{"0":"43"}},{"t":"case","label":"United States v. Spears","cite":"729 F.3d 753","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/729/753/","by":{"0":"33, 43"},"q":[{"src":"brief","b":0,"text":"every time a tax-return preparer claims an improper deduction","cite":"729 F.3d 753, 756"}]},{"t":"case","label":"United States v. Taylor","cite":"142 S. Ct. 2015","y":2022,"id":"2021/20-1459","sc":1,"by":{"0":"24","2":"8"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"by":{"0":"2, 14, 20, 39","1":"25, 30","2":"3"},"q":[{"src":"brief","b":0,"text":"[c]ourts should not assign federal criminal statutes a ‘breathtaking’ scope when a narrower reading is reasonable.","cite":"141 S. Ct. 1648, 1661"},{"src":"brief","b":1,"text":"follow that definition, even if it varies from a term’s ordinary meaning.","cite":"141 S. Ct. 1648, 1657"},{"src":"argument","who":"Mr. Fisher","text":"The Solicitor General itself recognized in this Court a couple terms ago that \"use\" can mean \"instrumental to.\" That was the definition they used from the dictionary in Van Buren."},{"src":"argument","who":"Mr. Fisher","text":"You know, the Court has had a lot of cases in recent years, I gave Marinello as one example, Van Buren was another recent example that held -- some of the honest services cases are examples where the Court has said not in -- not -- not so much the Rule of Lenity, but they've just said understanding what Congress meant by words, we would not assume Congress would sweep in vast arrays of conduct without doing it clearly."},{"src":"argument","who":"Justice Kavanaugh","text":"In the court of appeals, Judge Costa's opinion said that this Court's precedents had sent an \"unmistakable\" message that \"[c]ourts should not assign federal criminal statutes [of] a 'breath-taking' scope when a narrower reading is reasonable.\" And the Petitioner also cites a long line of cases you're familiar with, Marinello, Van Buren, Kelly, the list goes on, where we have rejected, I would say, the broadest interpretation of criminal statutes, the literal reading as compared to the ordinary reading of criminal statutes, based on fair notice concerns and not trapping the unwary or increasing the sentence on an unwary person."}]},{"t":"case","label":"Weyerhaeuser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"by":{"0":"24"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"0":"18"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"0":"2, 29, 30","1":"13"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"especially valuable Page Proof Pending Publication [where] it reinforces what the text's nouns and verbs independently suggest.","cite":"574 U. S. 528, 552"},{"src":"argument","who":"Mr. Fisher","text":"I think the high watermark perhaps for the -- for -- for the title mattering, if I could turn the Court back to criminal law, would be the Yates case, where the Court dealt with the -- the provision in the Sarbanes-Oxley Act that said that any tangible object was covered by the statute, and what the Court said was that -- was that \"records,\" the word in the title, limited actually the scope of that."},{"src":"argument","who":"Justice Kagan","text":"The dissent in Yates --"},{"src":"argument","who":"Mr. Fisher","text":"First of all, with due respect to the dissent in Yates, I'm not looking to use the title as -- as -- as aggressively as there. Really, there, the word \"records\" did limit the language quite directly."}]},{"t":"usc","label":"18 U.S.C. § 1028","url":"https://www.law.cornell.edu/uscode/text/18/1028","subs":["(a)(7)","(a)","(a)(6)","(d)(7)"],"stext":{"head":"§1028. Fraud and related activity in connection with identification documents, authentication features, and information","paras":[[0,"(a) Whoever, in a circumstance described in subsection (c) of this section—"],[1,"(1) knowingly and without lawful authority produces an identification document, authentication feature, or a false identification document;"],[1,"(2) knowingly transfers an identification document, authentication feature, or a false identification document knowing that such document or feature was stolen or produced without lawful authority;"],[1,"(3) knowingly possesses with intent to use unlawfully or transfer unlawfully five or more identification documents (other than those issued lawfully for the use of the possessor), authentication features, or false identification documents;"],[1,"(4) knowingly possesses an identification document (other than one issued lawfully for the use of the possessor), authentication feature, or a false identification document, with the intent such document or feature be used to defraud the United States;"],[1,"(5) knowingly produces, transfers, or possesses a document-making implement or authentication feature with the intent such document-making implement or authentication feature will be used in the production of a false identification document or another document-making implement or authentication feature which will be so used;"],[1,"(6) knowingly possesses an identification document or authentication feature that is or appears to be an identification document or authentication feature of the United States or a sponsoring entity of an event designated as a special event of national significance which is stolen or produced without lawful authority knowing that such document or feature was stolen or produced without such authority;"],[1,"(7) knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person with the intent to commit, or to aid or abet, or in connection with, any unlawful activity that constitutes a violation of Federal law, or that constitutes a felony under any applicable State or local law; or"],[1,"(8) knowingly traffics in false or actual authentication features for use in false identification documents, document-making implements, or means of identification;"],[0,"shall be punished as provided in subsection (b) of this section."],[0,"(b) The punishment for an offense under subsection (a) of this section is—"],[1,"(1) except as provided in paragraphs (3) and (4), a fine under this title or imprisonment for not more than 15 years, or both, if the offense is—"],[2,"(A) the production or transfer of an identification document, authentication feature, or false identification document that is or appears to be—"],[3,"(i) an identification document or authentication feature issued by or under the authority of the United States; or"],[3,"(ii) a birth certificate, or a driver's license or personal identification card;"],[2,"(B) the production or transfer of more than five identification documents, authentication features, or false identification documents;"],[2,"(C) an offense under paragraph (5) of such subsection; or"],[2,"(D) an offense under paragraph (7) of such subsection that involves the transfer, possession, or use of 1 or more means of identification if, as a result of the offense, any individual committing the offense obtains anything of value aggregating $1,000 or more during any 1-year period;"],[1,"(2) except as provided in paragraphs (3) and (4), a fine under this title or imprisonment for not more than 5 years, or both, if the offense is—"],[2,"(A) any other production, transfer, or use of a means of identification, an identification document,,1 authentication feature, or a false identification document; or"],[2,"(B) an offense under paragraph (3) or (7) of such subsection;"],[1,"(3) a fine under this title or imprisonment for not more than 20 years, or both, if the offense is committed—"],[2,"(A) to facilitate a drug trafficking crime (as defined in section 929(a)(2));"],[2,"(B) in connection with a crime of violence (as defined in section 924(c)(3)); or"],[2,"(C) after a prior conviction under this section becomes final;"],[1,"(4) a fine under this title or imprisonment for not more than 30 years, or both, if the offense is committed to facilitate an act of domestic terrorism (as defined under section 2331(5) of this title) or an act of international terrorism (as defined in section 2331(1) of this title);"],[1,"(5) in the case of any offense under subsection (a), forfeiture to the United States of any personal property used or intended to be used to commit the offense; and"],[1,"(6) a fine under this title or imprisonment for not more than one year, or both, in any other case."],[0,"(c) The circumstance referred to in subsection (a) of this section is that—"],[1,"(1) the identification document, authentication feature, or false identification document is or appears to be issued by or under the authority of the United States or a sponsoring entity of an event designated as a special event of national significance or the document-making implement is designed or suited for making such an identification document, authentication feature, or false identification document;"],[1,"(2) the offense is an offense under subsection (a)(4) of this section; or"],[1,"(3) either—"],[2,"(A) the production, transfer, possession, or use prohibited by this section is in or affects interstate or foreign commerce, including the transfer of a document by electronic means; or"],[2,"(B) the means of identification, identification document, false identification document, or document-making implement is transported in the mail in the course of the production, transfer, possession, or use prohibited by this section."],[0,"(d) In this section and section 1028A—"],[1,"(1) the term \"authentication feature\" means any hologram, watermark, certification, symbol, code, image, sequence of numbers or letters, or other feature that either individually or in combination with another feature is used by the issuing authority on an identification document, document-making implement, or means of identification to determine if the document is counterfeit, altered, or otherwise falsified;"],[1,"(2) the term \"document-making implement\" means any implement, impression, template, computer file, computer disc, electronic device, or computer hardware or software, that is specifically configured or primarily used for making an identification document, a false identification document, or another document-making implement;"],[1,"(3) the term \"identification document\" means a document made or issued by or under the authority of the United States Government, a State, political subdivision of a State, a sponsoring entity of an event designated as a special event of national significance, a foreign government, political subdivision of a foreign government, an international governmental or an international quasi-governmental organization which, when completed with information concerning a particular individual, is of a type intended or commonly accepted for the purpose of identification of individuals;"],[1,"(4) the term \"false identification document\" means a document of a type intended or commonly accepted for the purposes of identification of individuals that—"],[2,"(A) is not issued by or under the authority of a governmental entity or was issued under the authority of a governmental entity but was subsequently altered for purposes of deceit; and"],[2,"(B) appears to be issued by or under the authority of the United States Government, a State, a political subdivision of a State, a sponsoring entity of an event designated by the President as a special event of national significance, a foreign government, a political subdivision of a foreign government, or an international governmental or quasi-governmental organization;"],[1,"(5) the term \"false authentication feature\" means an authentication feature that—"],[2,"(A) is genuine in origin, but, without the authorization of the issuing authority, has been tampered with or altered for purposes of deceit;"],[2,"(B) is genuine, but has been distributed, or is intended for distribution, without the authorization of the issuing authority and not in connection with a lawfully made identification document, document-making implement, or means of identification to which such authentication feature is intended to be affixed or embedded by the respective issuing authority; or"],[2,"(C) appears to be genuine, but is not;"],[1,"(6) the term \"issuing authority\"—"],[2,"(A) means any governmental entity or agency that is authorized to issue identification documents, means of identification, or authentication features; and"],[2,"(B) includes the United States Government, a State, a political subdivision of a State, a sponsoring entity of an event designated by the President as a special event of national significance, a foreign government, a political subdivision of a foreign government, or an international government or quasi-governmental organization;"],[1,"(7) the term \"means of identification\" means any name or number that may be used, alone or in conjunction with any other information, to identify a specific individual, including any—"],[2,"(A) name, social security number, date of birth, official State or government issued driver's license or identification number, alien registration number, government passport number, employer or taxpayer identification number;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1028?type=usc&year=mostrecent&link-type=html"},"by":{"0":"16, 35, 36","1":"19, 20, 20, 34, 20","2":"20, 21"},"q":[{"src":"brief","b":0,"text":"knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person with the intent to commit, or to aid or abet, or in connection with, any unlawful activity that constitutes a violation of Federal law, or that constitutes a felony under any applicable State or local law.","cite":"18 U.S.C. § 1028(a)(7)"},{"src":"brief","b":1,"text":"any name or number that may be used, alone or in conjunction with any other information, to identify a specific individual.","cite":"18 U.S.C. 1028(d)(7)"}]},{"t":"usc","label":"18 U.S.C. § 1028A","url":"https://www.law.cornell.edu/uscode/text/18/1028A","subs":["(a)(1)","(b)","(c)","(a)(2)","(b)(1)"],"stext":{"head":"§1028A. Aggravated identity theft","paras":[[0,"(a) Offenses.—"],[1,"(1) In general.—Whoever, during and in relation to any felony violation enumerated in subsection (c), knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person shall, in addition to the punishment provided for such felony, be sentenced to a term of imprisonment of 2 years."],[1,"(2) Terrorism offense.—Whoever, during and in relation to any felony violation enumerated in section 2332b(g)(5)(B), knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person or a false identification document shall, in addition to the punishment provided for such felony, be sentenced to a term of imprisonment of 5 years."],[0,"(b) Consecutive Sentence.—Notwithstanding any other provision of law—"],[1,"(1) a court shall not place on probation any person convicted of a violation of this section;"],[1,"(2) except as provided in paragraph (4), no term of imprisonment imposed on a person under this section shall run concurrently with any other term of imprisonment imposed on the person under any other provision of law, including any term of imprisonment imposed for the felony during which the means of identification was transferred, possessed, or used;"],[1,"(3) in determining any term of imprisonment to be imposed for the felony during which the means of identification was transferred, possessed, or used, a court shall not in any way reduce the term to be imposed for such crime so as to compensate for, or otherwise take into account, any separate term of imprisonment imposed or to be imposed for a violation of this section; and"],[1,"(4) a term of imprisonment imposed on a person for a violation of this section may, in the discretion of the court, run concurrently, in whole or in part, only with another term of imprisonment that is imposed by the court at the same time on that person for an additional violation of this section, provided that such discretion shall be exercised in accordance with any applicable guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28."],[0,"(c) Definition.—For purposes of this section, the term \"felony violation enumerated in subsection (c)\" means any offense that is a felony violation of—"],[1,"(1) section 641 (relating to theft of public money, property, or rewards 1), section 656 (relating to theft, embezzlement, or misapplication by bank officer or employee), or section 664 (relating to theft from employee benefit plans);"],[1,"(2) section 911 (relating to false personation of citizenship);"],[1,"(3) section 922(a)(6) (relating to false statements in connection with the acquisition of a firearm);"],[1,"(4) any provision contained in this chapter (relating to fraud and false statements), other than this section or section 1028(a)(7);"],[1,"(5) any provision contained in chapter 63 (relating to mail, bank, and wire fraud);"],[1,"(6) any provision contained in chapter 69 (relating to nationality and citizenship);"],[1,"(7) any provision contained in chapter 75 (relating to passports and visas);"],[1,"(8) section 523 of the Gramm-Leach-Bliley Act (15 U.S.C. 6823) (relating to obtaining customer information by false pretenses);"],[1,"(9) section 243 or 266 of the Immigration and Nationality Act (8 U.S.C. 1253 and 1306) (relating to willfully failing to leave the United States after deportation and creating a counterfeit alien registration card);"],[1,"(10) any provision contained in chapter 8 of title II of the Immigration and Nationality Act (8 U.S.C. 1321 et seq.) (relating to various immigration offenses); or"],[1,"(11) section 208, 811, 1107(b), 1128B(a), or 1632 of the Social Security Act (42 U.S.C. 408, 1011, 1307(b), 1320a–7b(a), and 1383a) (relating to false statements relating to programs under the Act)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1028A?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, passim, 6, 32, 5","1":"20, 20, 20, 20, 20, 20, 20","2":"1-8, 10-11, 13-14, 16-22, 5, 6, 11, 15"},"q":[{"src":"brief","b":0,"text":"during and in relation to any [predicate felony violation], knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person.","cite":"18 U.S.C. § 1028A"},{"src":"brief","b":0,"text":"crimes in which someone wrongfully obtains and uses another person’s personal data in some way that involves fraud or deception.","cite":"18 U.S.C. § 1028A"},{"src":"brief","b":1,"text":"knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person.","cite":"18 U.S.C. 1028A(a)(1)"},{"src":"brief","b":1,"text":"us[ing], without lawful authority, a means of identification,","cite":"18 U.S.C. 1028A(a)(1)"},{"src":"argument","who":"Mr. Fisher","text":"Dubin's conduct fall within the terms of Section 1028A. First, he did not use Patient L's name in relation to his healthcare fraud offense."}]},{"t":"usc","label":"18 U.S.C. § 1030","url":"https://www.law.cornell.edu/uscode/text/18/1030","subs":["(a)(2)","(e)(6)"],"by":{"0":"20, 20"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","by":{"0":"34"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","by":{"0":"33, 34, 38"}},{"t":"usc","label":"18 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/18/1344","stext":{"head":"§1344. Bank fraud","paras":[[0,"Whoever knowingly executes, or attempts to execute, a scheme or artifice—"],[1,"(1) to defraud a financial institution; or"],[1,"(2) to obtain any of the moneys, funds, credits, assets, securities, or other property owned by, or under the custody or control of, a financial institution, by means of false or fraudulent pretenses, representations, or promises;"],[0,"shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1344?type=usc&year=mostrecent&link-type=html"},"by":{"0":"33, 38","2":"7"}},{"t":"usc","label":"18 U.S.C. § 1347","url":"https://www.law.cornell.edu/uscode/text/18/1347","subs":["(a)(2)","(a)"],"stext":{"head":"§1347. Health care fraud","paras":[[0,"(a) Whoever knowingly and willfully executes, or attempts to execute, a scheme or artifice—"],[1,"(1) to defraud any health care benefit program; or"],[1,"(2) to obtain, by means of false or fraudulent pretenses, representations, or promises, any of the money or property owned by, or under the custody or control of, any health care benefit program,"],[0,"in connection with the delivery of or payment for health care benefits, items, or services, shall be fined under this title or imprisoned not more than 10 years, or both. If the violation results in serious bodily injury (as defined in section 1365 of this title), such person shall be fined under this title or imprisoned not more than 20 years, or both; and if the violation results in death, such person shall be fined under this title, or imprisoned for any term of years or for life, or both."],[0,"(b) With respect to violations of this section, a person need not have actual knowledge of this section or specific intent to commit a violation of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1347?type=usc&year=mostrecent&link-type=html"},"by":{"0":"32, 38","1":"2, 3, 16","2":"5, 7"},"q":[{"src":"argument","who":"Mr. Fisher","text":"It would have violated Section 1347 because it covers artifices and schemes that attempt to defraud the government. So, even if the bill had not been paid, it still would have been healthcare fraud."}]},{"t":"usc","label":"18 U.S.C. § 1519","url":"https://www.law.cornell.edu/uscode/text/18/1519","by":{"0":"29"}},{"t":"law","label":"Identity Theft Penalty Enhancement Act, Pub. L. No. 108-275","url":"https://www.govinfo.gov/link/plaw/108/public/275","by":{"0":"5, 28, 29","1":"11"}},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"ordinarily resist[s] reading words or elements into a statute that do not appear on its face.","cite":"522 U.S. 23, 29"}]},{"t":"case","label":"(III) Cases—Continued: Birchfield v. North Dakota","cite":"579 U.S. 438","y":2016,"id":"2015/14-1468","sc":1,"by":{"1":"15"},"q":[{"src":"brief","b":1,"text":"need not be express but may be fairly inferred from context.","cite":"579 U.S. 438, 476"}]},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"by":{"1":"11, 12"},"q":[{"src":"brief","b":1,"text":"cannot be the result of accident or coincidence.","cite":"556 U.S. at 573"}]},{"t":"case","label":"DePierre v. United States","cite":"564 U.S. 70","y":2011,"id":"2010/09-1533","sc":1,"by":{"1":"26"}},{"t":"case","label":"Florida v. Jardines","cite":"569 U.S. 1","y":2013,"id":"2012/11-564","sc":1,"by":{"1":"32"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"141 S. Ct. 1868","y":2021,"id":"2020/19-123","sc":1,"by":{"1":"23, 24"},"q":[{"src":"brief","b":1,"text":"title or heading should never be allowed to override the plain words of a text.","cite":"141 S. Ct. 1868, 1879"}]},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"1":"34, 35"},"q":[{"src":"brief","b":1,"text":"comes into play only when, after the application of ordinary textual analysis, the statute is found to be susceptible of more than one construction.","cite":"138 S. Ct. 830, 842"}]},{"t":"case","label":"Lawson v. FMR LLC","cite":"571 U.S. 429","y":2014,"id":"2013/12-3","sc":1,"by":{"1":"25"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"by":{"1":"36","2":"4, 21"},"q":[{"src":"brief","b":1,"text":"not at the beginning as an overriding consideration of being lenient to wrongdoers.","cite":"570 U.S. 48, 76"}]},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"by":{"1":"11"},"q":[{"src":"brief","b":1,"text":"normally assume[s] that, when Congress enacts statutes, it is aware of relevant judicial precedent","cite":"559 U.S. 633, 648"}]},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"can make no more than a guess as to what Congress intended.","cite":"578 U.S. 282, 295 n.8"}]},{"t":"case","label":"Oncale v. Sundowner Offshore Services, Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"and it is ultimately the provisions of our laws rather than the principal concerns of our legislators by which we are governed.","cite":"523 U.S. 75, 79"}]},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"by":{"1":"37"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"[a]textual judicial supplementation is particularly inappropriate when, as here, Congress has shown that it knows how to adopt the omitted language.","cite":"140 S. Ct. 355, 361"}]},{"t":"case","label":"Schmuck v. United States","cite":"489 U.S. 705","y":1989,"id":"1988/87-6431","sc":1,"by":{"1":"32","2":"16"}},{"t":"case","label":"Trainmen v. Baltimore & Ohio R.R.","cite":"331 U.S. 519","y":1947,"id":"scdb/1946-111","sc":1,"by":{"1":"24, 25","2":"11"},"q":[{"src":"brief","b":1,"text":"they cannot undo or limit that which the text makes plain.","cite":"331 U.S. 519, 529"},{"src":"brief","b":1,"text":"indicate the provisions in a most general manner.","cite":"331 U.S. at 528"}]},{"t":"case","label":"Travelers Indemnity Co. v. Bailey","cite":"557 U.S. 137","y":2009,"id":"2008/08-295","sc":1,"by":{"1":"13"}},{"t":"case","label":"United States v. Abdelshafi","cite":"592 F.3d 602","y":2010,"url":"https://www.courtlistener.com/c/F.3d/592/602/","by":{"1":"18, 33"}},{"t":"case","label":"United States v. Burgos","cite":"137 F.3d 841","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/137/841/","by":{"1":"28, 29"},"q":[{"src":"brief","b":1,"text":"billed certain insurance companies for services that he did not provide to his patients.","cite":"137 F.3d 841, 842"}]},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"1":"36"}},{"t":"case","label":"United States v. Kelly-Tuorila","cite":"759 Fed. Appx. 236","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./759/236/","by":{"1":"5"}},{"t":"case","label":"United States v. Lucien","cite":"347 F.3d 45","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/347/45/","by":{"1":"33","2":"18"},"q":[{"src":"brief","b":2,"text":"can be committed in still other ways that do not involve using someone else’s means of identification,","cite":"347 F.3d 45"}]},{"t":"case","label":"United States v. Lumbard","cite":"706 F.3d 716","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/706/716/","by":{"1":"18"}},{"t":"case","label":"United States v. Oregon & California R.R.","cite":"164 U.S. 526","y":1896,"id":"scdb/1896-054","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"The ambiguity must be in the context and not in the title to render the latter of any avail.","cite":"164 U.S. 526, 541"}]},{"t":"case","label":"United States v. Osuna-Alvarez","cite":"788 F.3d 1183","y":2015,"url":"https://www.courtlistener.com/c/F.3d/788/1183/","by":{"1":"18"}},{"t":"case","label":"United States v. Ozuna-Cabrera","cite":"663 F.3d 496","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/663/496/","by":{"1":"18"}},{"t":"case","label":"United States v. Perry","cite":"757 F.3d 166","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/757/166/","by":{"1":"33"}},{"t":"case","label":"United States v. Retana","cite":"641 F.3d 272","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/641/272/","by":{"1":"18"}},{"t":"case","label":"United States v. Reynolds","cite":"710 F.3d 434","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/710/434/","by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"easily encompasses situations in which a defendant gains access to identity information legitimately but then uses it illegitimately.","cite":"710 F.3d 434, 436"}]},{"t":"case","label":"United States v. Ruiz","cite":"698 Fed. Appx. 978","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./698/978/","by":{"1":"33"}},{"t":"case","label":"United States v. Skodnek","cite":"933 F. Supp. 1108","y":1996,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp./933/1108/","by":{"1":"28"}},{"t":"case","label":"United States v. Smith","cite":"756 F.3d 1179","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1179/","by":{"1":"11"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"it may be difficult in some cases to determine whether [its] clear requirements have been met.","cite":"553 U.S. 285, 306"}]},{"t":"case","label":"United States v. Zitron","cite":"810 F.3d 1253","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/1253/","by":{"1":"19"}},{"t":"case","label":"Voisine v. United States","cite":"579 U.S. 686","y":2016,"id":"2015/14-10154","sc":1,"by":{"1":"36"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"by":{"1":"31, 37","2":"22, 23"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"2-4"}},{"t":"usc","label":"18 U.S.C. § 287","url":"https://www.law.cornell.edu/uscode/text/18/287","by":{"1":"16"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 499","url":"https://www.law.cornell.edu/uscode/text/18/499","stext":{"head":"§499. Military, naval, or official passes","paras":[[0,"Whoever falsely makes, forges, counterfeits, alters, or tampers with any naval, military, or official pass or permit, issued by or under the authority of the United States, or with intent to defraud uses or possesses any such pass or permit, or personates or falsely represents himself to be or not to be a person to whom such pass or permit has been duly issued, or willfully allows any other person to have or use any such pass or permit, issued for his use alone, shall be fined under this title or imprisoned not more than five years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/499?type=usc&year=mostrecent&link-type=html"},"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"personates or falsely represents himself to be * * * a person to whom [a military] pass or permit has been duly issued,","cite":"18 U.S.C. 499"}]},{"t":"usc","label":"18 U.S.C. § 913","url":"https://www.law.cornell.edu/uscode/text/18/913","by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"falsely represents himself to be an officer, agent, or employee of the United States,","cite":"18 U.S.C. 913"}]},{"t":"usc","label":"18 U.S.C. § 915","url":"https://www.law.cornell.edu/uscode/text/18/915","by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"falsely assumes or pretends to be","cite":"18 U.S.C. 915"}]},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)","(c)(1)(A)","(d)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"1":"11, 12, 35, 11, 11","2":"4"}},{"t":"usc","label":"18 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/18/1342","by":{"1":"20"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"1":"2, 3"}},{"t":"usc","label":"18 U.S.C. § 1424","url":"https://www.law.cornell.edu/uscode/text/18/1424","by":{"1":"21"}},{"t":"usc","label":"42 U.S.C. § 1320a-7b","url":"https://www.law.cornell.edu/uscode/text/42/1320a-7b","subs":["(b)(2)"],"by":{"1":"16, 3"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(b)"],"by":{"1":"6"}},{"t":"case","label":"Doe v. McMillan","cite":"412 U.S. 306","y":1973,"id":"1972/71-6356","sc":1,"by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"has always been tied to the scope of [his] authority.","cite":"412 U.S. 306, 320"}]},{"t":"case","label":"N.L.R.B. v. SW. Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"2":"14"},"q":[{"src":"brief","b":2,"text":"[f]loor statements by individual legislators rank among the least illuminating forms of legislative history.","cite":"580 U.S. 288, 307"}]},{"t":"case","label":"N.Y. State Conf. of Blue Cross & Blue Shield Plans v. Travelers Ins. Co.","cite":"514 U.S. 645","y":1995,"id":"1994/93-1408","sc":1,"by":{"2":"4"}},{"t":"case","label":"Stump v. Sparkman","cite":"435 U.S. 349","y":1978,"id":"1977/76-1750","sc":1,"by":{"2":"9"}},{"t":"case","label":"United States v. Coffman","cite":"94 F.3d 330","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/94/330/","by":{"2":"7"}},{"t":"case","label":"United States v. Kimble","cite":"2015 WL 4164820","y":2015,"court":"D. Md. July 8","by":{"2":"19"}},{"t":"case","label":"United States v. Spurgeon","cite":"117 F.3d 641","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/117/641/","by":{"2":"21"}},{"t":"case","label":"United States v. Stokes","cite":"392 Fed. Appx. 362","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./392/362/","by":{"2":"15"}},{"t":"case","label":"Zedner v. United States","cite":"547 U.S. 489","y":2006,"id":"2005/05-5992","sc":1,"by":{"2":"7"}},{"t":"usc","label":"15 U.S.C. § 6151","url":"https://www.law.cornell.edu/uscode/text/15/6151","by":{"2":"17"}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(a)"],"by":{"2":"4"}},{"t":"usc","label":"42 U.S.C. § 1396d","url":"https://www.law.cornell.edu/uscode/text/42/1396d","subs":["(a)(31)(A)"],"by":{"2":"7"}},{"t":"usc","label":"47 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/47/227","by":{"2":"16"}},{"t":"reg","label":"16 C.F.R. § 310.4","url":"https://www.ecfr.gov/current/title-16/section-310.4","subs":["(b)(1)(iii)"],"by":{"2":"17"}}]};